// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newImpl) public {
        // Ensure newImpl is not zero address to avoid revert in reference
        vm.assume(newImpl != address(0));
        // Ensure caller is not zero address to avoid issues
        vm.assume(caller != address(0));

        // Set caller as the caller for the function
        vm.prank(caller);

        // Attempt to call updateRoundImplementation
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.updateRoundImplementation.selector, newImpl));

        // The rule: only the owner (which is the deployer, address(this)) can successfully update
        assertTrue(success == (caller == address(this)));
    }
}

